import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene positioning from config or spec defaults
  const pos = config.scenePosition || [-3.2, 1, 0.06];
  const rot = config.sceneRotation || [0, 0, 0];
  const scl = config.sceneScale || [1, 1, 1];
  const imageUrl = config.assets?.[0]?.url || '/prism-mock/home/nodes/orb-decor.png';
  const textContent = config.textContent || 'Pricing 1';

  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  // Load the orb-decor background texture
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry (512x320 aspect ratio ≈ 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // TSL shader nodes for engineered static composition
  const { texture: texNode, uv, noise, mix, vec3 } = TSL;

  const baseTexture = texNode(texture);

  // Subtle engineered grain texture overlay
  const grainOverlay = noise(uv().mul(20)).mul(0.08);

  // Engineered gradient surface: vertical blend from surface (#0b0b10) to paper (#e8ecf2)
  const verticalGrad = uv().y;
  const surfaceColor = vec3(0.043, 0.043, 0.063);  // near-black surface
  const paperColor = vec3(0.91, 0.925, 0.949);    // paper white
  const gradientSurface = mix(surfaceColor, paperColor, verticalGrad.mul(0.25));

  // Composite: base texture blended with gradient, then add grain
  const finalColor = mix(baseTexture, gradientSurface, 0.12).add(grainOverlay);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content via MSDF fontAtlas
  const textMesh = ctx.fontAtlas(textContent, {
    fontSize: 0.34,        // headline size in scene units
    fontFamily: 'Lora',
    fontWeight: 400,
    color: '#e8ecf2'       // paper color for contrast
  });

  if (textMesh) {
    textMesh.position.y = 0.2;  // Position text above the card
    group.add(textMesh);
  }

  // Setup resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
